from sys import stdin, stdout

def max_defended_score(n, m, k, castles, portals):
    INF = float('inf')
    adj = [[] for _ in range(n)]

    # Build adjacency list for portals
    for u, v in portals:
        adj[u-1].append(v-1)

    dp = [[[-INF] * (k + 1) for _ in range(n)] for _ in range(2)]
    dp[0][0][k] = 0

    for i in range(n):
        cur_dp, nxt_dp = dp[i % 2], dp[(i + 1) % 2]
        nxt_dp.clear()

        for j in range(k + 1):
            for x in range(n):
                if dp[i % 2][x][j] == -INF:
                    continue

                # Option to move to the next castle
                if j >= castles[x][0]:
                    nxt_dp[x][j - castles[x][0]] = max(nxt_dp[x][j - castles[x][0]], dp[i % 2][x][j])

                # Option to defend the current castle
                if j >= 1:
                    nxt_dp[x][j - 1] = max(nxt_dp[x][j - 1], dp[i % 2][x][j] + castles[x][2])

                # Option to use portals
                for y in adj[x]:
                    if j >= 1:
                        nxt_dp[y][j - 1] = max(nxt_dp[y][j - 1], dp[i % 2][x][j])

    return max(max(row) for row in dp[(n - 1) % 2])

# Read input
n, m, k = map(int, stdin.readline().split())
castles = [list(map(int, stdin.readline().split())) for _ in range(n)]
portals = [tuple(map(int, stdin.readline().split())) for _ in range(m)]

# Write output
stdout.write(str(max_defended_score(n, m, k, castles, portals)))
